CREATE TABLE public.device_qr_credentials (wallet uuid PRIMARY KEY REFERENCES public.device_wallet_access(credential_handle), recovery_hash text NOT NULL, device_hash text NOT NULL, generation integer NOT NULL DEFAULT 1, mailbox_user uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.device_qr_credentials TO service_role;
ALTER TABLE public.device_qr_credentials ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX device_qr_mailbox_user ON public.device_qr_credentials(mailbox_user);
CREATE OR REPLACE FUNCTION public.move_qr_device(p_wallet uuid,p_recovery text,p_device text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g integer; BEGIN UPDATE public.device_qr_credentials SET device_hash=p_device,generation=generation+1 WHERE wallet=p_wallet AND recovery_hash=p_recovery RETURNING generation INTO g; IF g IS NULL THEN RAISE EXCEPTION 'Invalid private access code'; END IF; DELETE FROM public.wallet_push_subscriptions WHERE wallet=p_wallet; RETURN g; END; $$;
REVOKE ALL ON FUNCTION public.move_qr_device(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.move_qr_device(uuid,text,text) TO service_role;
COMMENT ON TABLE public.device_qr_credentials IS 'Private QR recovery and single active device authority. Public room QRs contain no credentials.';
CREATE OR REPLACE FUNCTION public.tick_device_wallet_usage(p_handle uuid) RETURNS TABLE(used_seconds integer,resets_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.device_wallet_usage; BEGIN INSERT INTO public.device_wallet_usage(credential_handle) VALUES(p_handle) ON CONFLICT DO NOTHING; SELECT * INTO u FROM public.device_wallet_usage WHERE credential_handle=p_handle FOR UPDATE; IF u.window_started+interval '24 hours'<=now() THEN u.window_started:=now();u.used_seconds:=0;u.last_tick:=NULL; END IF; IF u.last_tick IS NOT NULL THEN u.used_seconds:=LEAST(2700,u.used_seconds+GREATEST(0,LEAST(5,floor(extract(epoch FROM now()-u.last_tick))::integer))); END IF; UPDATE public.device_wallet_usage SET window_started=u.window_started,used_seconds=u.used_seconds,last_tick=now(),share_bonus_expires_at=NULL WHERE credential_handle=p_handle; RETURN QUERY SELECT u.used_seconds,u.window_started+interval '24 hours'; END; $$;